'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createInventory']);
const { createInventory } = api;

for (const value of [null, [], 'x', 4]) {
  assert.throws(() => createInventory(value), TypeError);
}
assert.throws(() => createInventory({ '': 1 }), TypeError);
assert.throws(() => createInventory({ a: 1.5 }), TypeError);
assert.throws(() => createInventory({ a: NaN }), TypeError);
assert.throws(() => createInventory({ a: -1 }), RangeError);

const empty = createInventory({});
assert.deepStrictEqual(empty.snapshot(), { stock: {}, reservations: [] });
assert.throws(() => empty.reserve([]), TypeError);
assert.throws(() => empty.reserve('bad'), TypeError);

const source = { z: 4, a: 8, m: 0 };
const inventory = createInventory(source);
source.a = 100;
source.extra = 9;
let snap = inventory.snapshot();
assert.deepStrictEqual(Object.keys(snap.stock), ['a', 'm', 'z']);
assert.deepStrictEqual(snap, { stock: { a: 8, m: 0, z: 4 }, reservations: [] });

const first = inventory.reserve([
  { sku: 'z', quantity: 1 },
  { sku: 'a', quantity: 2 },
  { sku: 'z', quantity: 2 }
]);
assert.deepStrictEqual(first, {
  id: 'r1',
  lines: [{ sku: 'z', quantity: 3 }, { sku: 'a', quantity: 2 }]
});
assert.deepStrictEqual(inventory.snapshot(), {
  stock: { a: 6, m: 0, z: 1 },
  reservations: [{ id: 'r1', lines: [{ sku: 'z', quantity: 3 }, { sku: 'a', quantity: 2 }] }]
});

first.lines[0].quantity = 999;
first.lines.push({ sku: 'a', quantity: 1 });
snap = inventory.snapshot();
snap.stock.a = 999;
snap.reservations[0].lines[0].quantity = 999;
assert.deepStrictEqual(inventory.snapshot(), {
  stock: { a: 6, m: 0, z: 1 },
  reservations: [{ id: 'r1', lines: [{ sku: 'z', quantity: 3 }, { sku: 'a', quantity: 2 }] }]
});

const beforeFailure = inventory.snapshot();
assert.strictEqual(inventory.reserve([{ sku: 'a', quantity: 1 }, { sku: 'z', quantity: 2 }]), null);
assert.deepStrictEqual(inventory.snapshot(), beforeFailure);
assert.strictEqual(inventory.reserve([{ sku: 'missing', quantity: 1 }]), null);
assert.deepStrictEqual(inventory.snapshot(), beforeFailure);

for (const lines of [
  null,
  [{}],
  [{ sku: '', quantity: 1 }],
  [{ sku: 'a', quantity: 0 }],
  [{ sku: 'a', quantity: 1.2 }],
  [{ sku: 'a', quantity: 1 }, null]
]) {
  assert.throws(() => inventory.reserve(lines), error => error instanceof TypeError || error instanceof RangeError);
  assert.deepStrictEqual(inventory.snapshot(), beforeFailure);
}

const second = inventory.reserve([{ sku: 'a', quantity: 1 }]);
assert.strictEqual(second.id, 'r2');
assert.strictEqual(inventory.release('r1'), true);
assert.deepStrictEqual(inventory.snapshot(), {
  stock: { a: 7, m: 0, z: 4 },
  reservations: [{ id: 'r2', lines: [{ sku: 'a', quantity: 1 }] }]
});
assert.strictEqual(inventory.release('r1'), false);
assert.strictEqual(inventory.release('unknown'), false);
assert.strictEqual(inventory.release('r2'), true);
assert.deepStrictEqual(inventory.snapshot(), { stock: { a: 8, m: 0, z: 4 }, reservations: [] });

